  let out = text;
  for (const { pattern, replacement } of PHRASE_SYNONYMS) {
    out = out.replace(pattern, replacement);
  }
  return out;
}

export function expandTokenSynonyms(token: string): string[] {
  const syns = TOKEN_SYNONYMS[token];
  if (!syns) return [token];
  return [...new Set([token, ...syns])];
}

export function expandTokenSynonymsList(tokens: string[]): string[] {
  const out = new Set<string>();
  for (const token of tokens) {
    for (const s of expandTokenSynonyms(token)) out.add(s);
  }
  return [...out];
}

import { extractPackCount } from "./normalizeUtterance.ts";

export function extractOrderQuantity(text: string): number {
  const pack = extractPackCount(text);
  if (pack != null && pack > 0) return pack;

  const trimmed = text.trim();
  const leading = trimmed.match(/^\s*(\d{1,4})\b/);
  if (leading) {
    const value = Number(leading[1]);
    if (value > 0) return value;
  }

  const unitQty = trimmed.match(/\b(\d{1,4})\s*(?:kg|kilo|g|gm|gms|gram|box|boxes|pkt|pack)\b/i);
  if (unitQty) {
    const value = Number(unitQty[1]);
    if (value > 0) return value;
  }

  return 1;
}

